"""任务引擎 — 运行时任务状态机与生命周期管理。

借鉴经验:
- QM: CAS 状态转换 + TaskEvent 审计日志
- OpenOPC: retry_count/max_retries、priority(1-10)、execution_lock
- Multica: 21+ 细分失败原因（error_type 分类）
- hermes-agent: RailTask 实时进度跟踪

状态机:
  pending -> running -> completed/failed
  failed -> pending (重试, retry_count < max_retries)
  running -> cancelled
  pending -> cancelled
"""
import logging
import time
import uuid
from datetime import datetime

logger = logging.getLogger('agent.task_engine')

# 合法的状态转换映射
_VALID_TRANSITIONS = {
    'pending': ('running', 'cancelled'),
    'running': ('completed', 'failed', 'cancelled'),
    'failed': ('pending',),   # 重试时回到 pending
    'completed': (),
    'cancelled': (),
}

# 失败分类（借鉴 Multica 21+ 细分失败原因）
ERROR_TYPES = (
    'timeout',           # 执行超时
    'llm_error',         # LLM 调用失败
    'tool_error',        # 工具执行失败
    'network_error',     # 网络错误
    'permission_error',  # 权限不足
    'resource_error',    # 资源不足（磁盘/内存）
    'cancelled',         # 用户取消
    'unknown',           # 未知错误
)


class TaskEngine:
    """任务引擎 — 管理运行时任务的生命周期。

    职责:
    - 创建/取消/重试任务
    - CAS 状态转换（防止并发竞争）
    - 自动重试（retry_count < max_retries 时回退到 pending）
    - 进度上报
    - 审计事件记录
    """

    def __init__(self, db, ws_client=None, agent_id=None):
        """初始化任务引擎。

        参数:
            db: Database 实例
            ws_client: WS 客户端（用于向平台上报进度）
            agent_id: Agent ID
        """
        self.db = db
        self.ws_client = ws_client
        self.agent_id = agent_id

    def _sync_to_platform(self, task, event_type='created'):
        """将任务状态同步到平台（如果 WS 已连接）。

        支持从异步上下文和同步线程中调用。
        """
        if not self.ws_client or not self.ws_client.connected:
            return
        from agent_runtime.ws import protocol
        task_data = {
            'runtime_task_id': task.get('id', ''),
            'message': task.get('message', '')[:500],
            'status': task.get('status', ''),
            'kind': task.get('kind', 'chat'),
            'priority': task.get('priority', 5),
            'progress': task.get('progress', 0),
            'token_used': task.get('token_used', 0),
            'result': (task.get('result', '') or '')[:5000],
            'error_type': task.get('error_type', '') or '',
            'error_message': (task.get('error_message', '') or '')[:500],
            'completed_at': task.get('completed_at', '') or '',
            'parent_id': task.get('parent_id', '') or '',
            'retry_count': task.get('retry_count', 0),
            'max_retries': task.get('max_retries', 3),
            'runtime_project_id': task.get('project_id', '') or '',
            'event_type': event_type,
            'agent_id': self.agent_id or '',
        }
        msg = protocol.make_agent_task_sync(task_data)
        loop = getattr(self.ws_client, 'loop', None) or getattr(self.ws_client, '_loop', None)
        if loop and loop.is_running():
            # 从同步线程调度异步发送
            import asyncio
            asyncio.run_coroutine_threadsafe(
                self.ws_client.send(msg), loop)
        else:
            # 可能在异步上下文中（直接 await 不可行，因为这是同步方法）
            try:
                running_loop = asyncio.get_running_loop()
                running_loop.create_task(self.ws_client.send(msg))
            except RuntimeError:
                logger.debug('平台同步跳过: 无可用事件循环')

    def create_task(self, message, kind='chat', priority=5,
                    parent_id=None, max_retries=3,
                    session_id=None, platform_task_id=None,
                    task_id=None, project_id=None):
        """创建新任务。

        参数:
            message: 任务描述
            kind: 来源类型 (chat/project/scheduled/subtask)
            priority: 优先级 1-10 (1=最高)
            parent_id: 父任务 ID（子任务时）
            max_retries: 最大重试次数
            session_id: 关联会话
            platform_task_id: 平台任务 ID（平台委派时）
            task_id: 自定义任务 ID（不指定则自动生成）
            project_id: 关联项目 ID（运行时项目 ID）

        返回:
            dict: 任务记录
        """
        if task_id is None:
            task_id = 'task-%s' % uuid.uuid4().hex[:12]

        task = self.db.create_task(
            task_id=task_id,
            message=message,
            parent_id=parent_id,
            kind=kind,
            priority=priority,
            max_retries=max_retries,
            session_id=session_id,
            platform_task_id=platform_task_id,
            project_id=project_id,
        )
        logger.info('任务已创建: id=%s kind=%s priority=%d',
                    task_id, kind, priority)
        # 同步到平台（如果 WS 已连接）
        self._sync_to_platform(task, event_type='created')
        return task

    def start_task(self, task_id):
        """开始执行任务（pending -> running）。

        使用 CAS 转换，仅当状态为 pending 时才转换。
        返回是否成功启动。
        """
        ok = self.db.cas_transition(
            task_id, 'pending', 'running',
            message='开始执行')
        if ok:
            logger.info('任务已启动: %s', task_id)
            # 同步到平台
            task = self.db.get_task(task_id)
            if task:
                self._sync_to_platform(task, event_type='started')
        else:
            task = self.db.get_task(task_id)
            logger.warning('任务启动失败: %s (当前状态: %s)',
                          task_id, task.get('status') if task else '不存在')
        return ok

    def complete_task(self, task_id, result=None, evidence=None,
                      token_used=0):
        """完成任务（running -> completed）。"""
        ok = self.db.cas_transition(
            task_id, 'running', 'completed',
            message='执行完成', token_used=token_used)
        if ok:
            self.db.update_task(
                task_id,
                result=result,
                evidence=evidence,
                token_used=token_used,
                completed_at=datetime.now().isoformat(),
                progress=100,
            )
            logger.info('任务已完成: %s token=%d', task_id, token_used)
            # 同步到平台
            updated = self.db.get_task(task_id)
            if updated:
                self._sync_to_platform(updated, event_type='completed')
        return ok

    def fail_task(self, task_id, error_type='unknown',
                  error_message=None, token_used=0):
        """标记任务失败（running -> failed）。

        如果 retry_count < max_retries，自动重试（回到 pending）。
        """
        # 先标记为 failed
        ok = self.db.cas_transition(
            task_id, 'running', 'failed',
            message=error_message, token_used=token_used)
        if not ok:
            return False

        self.db.update_task(
            task_id,
            error_type=error_type,
            error_message=str(error_message)[:500] if error_message else None,
        )

        # 检查是否可自动重试
        task = self.db.get_task(task_id)
        if not task:
            return True
        retry_count = task.get('retry_count', 0) or 0
        max_retries = task.get('max_retries', 3) or 3

        if retry_count < max_retries:
            # 自动重试: failed -> pending
            retry_ok = self.db.cas_transition(
                task_id, 'failed', 'pending',
                message='自动重试 (%d/%d)' % (retry_count + 1, max_retries))
            if retry_ok:
                self.db.update_task(
                    task_id, retry_count=retry_count + 1)
                logger.info('任务自动重试: %s (%d/%d)',
                           task_id, retry_count + 1, max_retries)
                self.db.append_task_event(
                    task_id, 'retry',
                    from_status='failed', to_status='pending',
                    message='第 %d 次重试' % (retry_count + 1))
        else:
            logger.warning('任务失败且已达重试上限: %s (%d/%d)',
                          task_id, retry_count, max_retries)
            # 同步到平台（最终失败）
            self._sync_to_platform(task, event_type='failed')

        return True

    def cancel_task(self, task_id, message=None):
        """取消任务（pending/running -> cancelled）。"""
        task = self.db.get_task(task_id)
        if not task:
            return False
        current_status = task.get('status')
        if current_status not in ('pending', 'running'):
            logger.warning('任务无法取消: %s (当前状态: %s)',
                          task_id, current_status)
            return False
        ok = self.db.cas_transition(
            task_id, current_status, 'cancelled',
            message=message or '用户取消')
        if ok:
            self.db.update_task(
                task_id,
                completed_at=datetime.now().isoformat(),
                error_type='cancelled',
            )
            logger.info('任务已取消: %s', task_id)
        return ok

    def retry_task(self, task_id):
        """手动重试任务（failed -> pending）。

        不受 max_retries 限制（手动操作）。
        """
        ok = self.db.cas_transition(
            task_id, 'failed', 'pending',
            message='手动重试')
        if ok:
            self.db.update_task(
                task_id,
                retry_count=0,
                error_type=None,
                error_message=None,
            )
            logger.info('任务手动重试: %s', task_id)
        return ok

    def update_progress(self, task_id, progress, message=None):
        """更新任务进度（0-100）。

        仅 running 状态的任务可更新进度。
        """
        task = self.db.get_task(task_id)
        if not task or task.get('status') != 'running':
            return False
        self.db.update_task(task_id, progress=min(100, max(0, progress)))
        if message:
            self.db.append_task_event(
                task_id, 'progress',
                from_status='running', to_status='running',
                message='进度 %d%%: %s' % (progress, message[:200]))
        return True

    def get_task_detail(self, task_id):
        """获取任务详情（含审计事件和子任务）。"""
        task = self.db.get_task(task_id)
        if not task:
            return None
        task['events'] = self.db.get_task_events(task_id)
        task['subtasks'] = self.db.get_subtasks(task_id)
        return task

    def list_tasks(self, hours=48, limit=100, kind=None, status=None,
                   project_id=None):
        """列出任务（支持过滤）。"""
        return self.db.list_recent_tasks(
            hours=hours, limit=limit, kind=kind, status=status,
            project_id=project_id)

    def list_tasks_paginated(self, status=None, kind=None, project_id=None,
                             search=None, created_after=None, created_before=None,
                             limit=10, offset=0):
        """分页任务列表（支持多条件过滤）。"""
        items = self.db.list_tasks_paginated(
            status=status, kind=kind, project_id=project_id,
            search=search, created_after=created_after,
            created_before=created_before, limit=limit, offset=offset)
        total = self.db.count_tasks(
            status=status, kind=kind, project_id=project_id,
            search=search, created_after=created_after,
            created_before=created_before)
        return {'items': items, 'total': total}

    def get_stats(self):
        """获取任务统计。"""
        return self.db.get_task_stats()
